    <main class="max-w-4xl mx-auto px-4 sm:px-6 lg:px-10 py-16">
        <div class="space-y-8">
            <!-- Success Message Section -->
            <div class="text-center space-y-6">
                <div class="inline-flex items-center gap-2 px-4 py-2 rounded-full bg-green-100 text-green-700 text-sm font-bold">
                    <svg class="w-5 h-5" fill="currentColor" viewBox="0 0 20 20">
                        <path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"></path>
                    </svg>
                    Solicitud recibida
                </div>

                <h1 class="text-5xl sm:text-6xl font-black leading-tight text-black">
                    ¡Gracias por <span class="text-transparent bg-clip-text bg-gradient-to-r from-[#CF0A2C] to-[#F9BE00]">tu registro</span>!
                </h1>

                <p class="text-lg text-slate-600 leading-relaxed max-w-2xl mx-auto">
                    Tu solicitud ha sido <strong class="text-black">enviada exitosamente</strong> al equipo de Compras de GPT Services. Revisaremos tu información en las próximas <strong class="text-[#CF0A2C]">24 a 48 horas</strong>.
                </p>
            </div>

            <!-- What's Next Section -->
            <div class="bg-slate-50 border-l-4 border-[#F9BE00] p-8 rounded-lg max-w-2xl mx-auto">
                <h2 class="font-bold text-black text-xl mb-4 flex items-center gap-2">
                    <svg class="w-6 h-6 text-[#CF0A2C]" fill="currentColor" viewBox="0 0 20 20">
                        <path fill-rule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-7-4a1 1 0 11-2 0 1 1 0 012 0zM9 9a1 1 0 000 2v3a1 1 0 001 1h1a1 1 0 100-2v-3a1 1 0 00-1-1H9z" clip-rule="evenodd"></path>
                    </svg>
                    ¿Qué sigue?
                </h2>
                <ul class="space-y-3 text-slate-700">
                    <li class="flex items-start gap-3">
                        <svg class="w-6 h-6 text-green-600 flex-shrink-0 mt-0.5" fill="currentColor" viewBox="0 0 20 20">
                            <path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"></path>
                        </svg>
                        <span>Nuestro equipo validará tu documentación</span>
                    </li>
                    <li class="flex items-start gap-3">
                        <svg class="w-6 h-6 text-green-600 flex-shrink-0 mt-0.5" fill="currentColor" viewBox="0 0 20 20">
                            <path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"></path>
                        </svg>
                        <span>Te contactaremos si necesitamos información adicional</span>
                    </li>
                    <li class="flex items-start gap-3">
                        <svg class="w-6 h-6 text-green-600 flex-shrink-0 mt-0.5" fill="currentColor" viewBox="0 0 20 20">
                            <path fill-rule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zm3.707-9.293a1 1 0 00-1.414-1.414L9 10.586 7.707 9.293a1 1 0 00-1.414 1.414l2 2a1 1 0 001.414 0l4-4z" clip-rule="evenodd"></path>
                        </svg>
                        <span>Recibirás la aprobación y pasos finales por correo</span>
                    </li>
                </ul>
            </div>

            <!-- Action Button -->
            <div class="text-center pt-8">
                <a href="{{ route('providers.register') }}" class="inline-flex items-center justify-center gap-2 px-8 py-4 rounded-xl bg-black text-white font-bold shadow-lg hover:bg-[#CF0A2C] transition-all duration-300 transform hover:scale-105">
                    <svg class="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M12 4v16m8-8H4"></path>
                    </svg>
                    Enviar otra solicitud
                </a>
            </div>
        </div>
    </main>

    <!-- Footer -->
    <footer class="bg-slate-900 text-slate-400 py-8 px-4 mt-16">
